/* Local, versioned persistence. No data is sent to an AI provider or a server. */
const storageEngine={db:null,ready:false,queue:Promise.resolve(),error:'',lastSaved:null,hasPrevious:false};
const BACKUP_FORMAT='nhiphoc-backup',BACKUP_VERSION=1,MAX_FILE=20*1024*1024,MAX_FILES_TOTAL=50*1024*1024;
const cleanString=(v,n=10000)=>typeof v==='string'?v.slice(0,n):'';
const cleanList=(v,n=100)=>Array.isArray(v)?v.slice(0,n).filter(x=>typeof x==='string').map(x=>x.slice(0,1000)):[];
const validId=v=>typeof v==='string'&&/^[a-zA-Z0-9_-]{1,120}$/.test(v);
const validDay=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v+'T12:00:00Z'))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;
const validTime=v=>typeof v==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(v);
function checkedState(raw){
 if(!raw||typeof raw!=='object'||!Array.isArray(raw.courses)||!raw.courses.length||raw.courses.length>100||!Array.isArray(raw.files)||raw.files.length>1000)throw Error('Hồ sơ không đúng cấu trúc hoặc vượt giới hạn.');
 const ids=new Set(),fileIds=new Set();
 const files=raw.files.map(f=>{if(!f||!validId(f.id)||fileIds.has(f.id)||!cleanString(f.name,300))throw Error('Danh sách tài liệu không hợp lệ.');fileIds.add(f.id);return {id:f.id,name:cleanString(f.name,300),author:cleanString(f.author,300),kind:cleanString(f.kind,10),role:cleanString(f.role,100),sample:f.sample===true,pages:Number.isFinite(f.pages)?Math.max(0,Math.min(f.pages,100000)):0,hasBlob:f.hasBlob===true,bytes:Number.isFinite(f.bytes)?Math.max(0,Math.min(f.bytes,MAX_FILE)):0,excerpt:cleanString(f.excerpt,20000),range:cleanString(f.range,300)}});
 const courses=raw.courses.map(c=>{if(!c||!validId(c.id)||ids.has(c.id)||!cleanString(c.name,100)||!validDay(c.date)||!validTime(c.time))throw Error('Môn học hoặc ngày giờ trong hồ sơ không hợp lệ.');ids.add(c.id);const duration=Number(c.duration);if(!Number.isFinite(duration)||duration<5||duration>180)throw Error('Thời lượng buổi học không hợp lệ.');const m=c.memory||{};return {id:c.id,name:cleanString(c.name,100),goal:cleanString(c.goal,1000),icon:cleanString(c.icon,10)||'✳',color:['sage','clay','blue'].includes(c.color)?c.color:'sage',progress:Number.isFinite(c.progress)?Math.max(0,Math.min(100,c.progress)):0,lesson:cleanString(c.lesson,300),date:c.date,time:c.time,duration,notes:cleanString(c.notes,100000),messages:Array.isArray(c.messages)?c.messages.slice(-1000).filter(x=>x&&['user','assistant'].includes(x.role)&&typeof x.text==='string').map(x=>({role:x.role,text:x.text.slice(0,20000)})):[],sources:cleanList(c.sources,1000).filter(id=>fileIds.has(id)),primarySource:validId(c.primarySource)?c.primarySource:null,plan:c.plan===true,pace:cleanString(c.pace,100),quiz:c.quiz===true,handoffDraft:c.handoffDraft?{lesson:cleanString(c.handoffDraft.lesson,300),minutes:Math.min(180,Math.max(5,Number(c.handoffDraft.minutes)||30)),objective:cleanString(c.handoffDraft.objective,2000),request:cleanString(c.handoffDraft.request,3000),sourceIds:cleanList(c.handoffDraft.sourceIds,20).filter(id=>fileIds.has(id))}:null,memory:{mastered:cleanList(m.mastered),weak:cleanList(m.weak),nextLesson:cleanString(m.nextLesson,300),lastSummary:cleanString(m.lastSummary,10000)},packets:Array.isArray(c.packets)?c.packets.slice(-100).map(p=>{if(!p||!validId(p.id)||typeof p.prompt!=='string')throw Error('Gói học không hợp lệ.');return {id:p.id,createdAt:cleanString(p.createdAt,40),lesson:cleanString(p.lesson,300),minutes:Math.min(180,Math.max(5,Number(p.minutes)||30)),objective:cleanString(p.objective,2000),sourceIds:cleanList(p.sourceIds,1000).filter(id=>fileIds.has(id)),prompt:p.prompt.slice(0,100000)}}):[],sessions:Array.isArray(c.sessions)?c.sessions.slice(-500).map(s=>checkedSession(s,c.id)):[]}});
 for(const c of courses){if(new Set(c.sessions.map(s=>s.packetId)).size!==c.sessions.length)throw Error('Tổng kết trùng mã buổi trong bản sao lưu.');if(new Set(c.packets.map(p=>p.id)).size!==c.packets.length)throw Error('Gói học trùng mã buổi trong bản sao lưu.');}
 const sessionIds=new Set(),extraSessions=Array.isArray(raw.extraSessions)?raw.extraSessions.slice(0,2000).map(e=>{if(!e||!validId(e.id)||sessionIds.has(e.id)||!ids.has(e.courseId)||!validDay(e.date)||!validTime(e.time)||!Number.isFinite(e.duration)||e.duration<5||e.duration>180)throw Error('Lịch học trong bản sao lưu không hợp lệ.');sessionIds.add(e.id);return {id:e.id,courseId:e.courseId,title:cleanString(e.title,300),date:e.date,time:e.time,duration:e.duration}}):[];
 return {courses,files,extraSessions,calendarVersion:1,tele:Array.isArray(raw.tele)?raw.tele.slice(-1000).filter(m=>m&&['user','assistant'].includes(m.role)).map(m=>({role:m.role,text:cleanString(m.text,20000)})):[],learner:{name:cleanString(raw.learner?.name,100)||'Minh',preferences:cleanString(raw.learner?.preferences,3000)},updatedAt:cleanString(raw.updatedAt,40),schemaVersion:1};
}
function checkedSession(s,courseId){if(!s||!validId(s.packetId)||s.courseId!==courseId||typeof s.summary!=='string')throw Error('Lịch sử buổi học không hợp lệ.');const q=s.quiz;return {packetId:s.packetId,courseId,lesson:cleanString(s.lesson,300),summary:cleanString(s.summary,10000),mastered:cleanList(s.mastered),needsReview:cleanList(s.needsReview),nextLesson:cleanString(s.nextLesson,300),notes:cleanString(s.notes,10000),minutesStudied:Math.max(0,Math.min(600,Number(s.minutesStudied)||0)),quiz:q&&Number.isInteger(q.correct)&&Number.isInteger(q.total)&&q.total>=0&&q.correct>=0&&q.correct<=q.total?{correct:q.correct,total:q.total}:null,suggestedProgress:Number.isFinite(s.suggestedProgress)?Math.max(0,Math.min(100,s.suggestedProgress)):null,importedAt:cleanString(s.importedAt,40)}}
function openLearningDB(){return new Promise((resolve,reject)=>{if(typeof indexedDB==='undefined'){reject(Error('Trình duyệt chưa hỗ trợ IndexedDB.'));return}const req=indexedDB.open('nhiphoc-learning',1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('workspace'))db.createObjectStore('workspace');if(!db.objectStoreNames.contains('files'))db.createObjectStore('files',{keyPath:'id'})};req.onsuccess=()=>{req.result.onversionchange=()=>req.result.close();resolve(req.result)};req.onerror=()=>reject(req.error||Error('Không mở được bộ nhớ.'));req.onblocked=()=>reject(Error('Đóng các thẻ Nhịp học cũ rồi tải lại để mở bộ nhớ.'))})}
function dbRead(store,key){return new Promise((resolve,reject)=>{const tx=storageEngine.db.transaction(store,'readonly'),req=key===undefined?tx.objectStore(store).getAll():tx.objectStore(store).get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function dbWrite(stores,fn){return new Promise((resolve,reject)=>{const tx=storageEngine.db.transaction(stores,'readwrite');try{fn(tx)}catch(e){tx.abort();reject(e);return}tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||Error('Không ghi được dữ liệu.'));tx.onabort=()=>reject(tx.error||Error('Đã hủy ghi dữ liệu.'))})}
function storageLabel(text){const el=document.querySelector('.connection');if(el)el.textContent=text}
function save(){state.updatedAt=new Date().toISOString();const snapshot=structuredClone(state);try{localStorage.setItem('nhiphoc-v2',JSON.stringify(snapshot))}catch(e){if(!storageEngine.db)storageEngine.error='Bộ nhớ trình duyệt đã đầy hoặc bị chặn.'}if(!storageEngine.ready||!storageEngine.db)return;storageLabel('Đang lưu trên máy…');storageEngine.queue=storageEngine.queue.catch(()=>{}).then(()=>dbWrite(['workspace'],tx=>tx.objectStore('workspace').put(snapshot,'current'))).then(()=>{storageEngine.lastSaved=snapshot.updatedAt;storageEngine.error='';storageLabel('✓ Đã lưu trên máy')}).catch(e=>{storageEngine.error=e.message||'Không lưu được dữ liệu.';storageLabel('Chưa lưu được · hãy xuất sao lưu');toast('Chưa lưu được hồ sơ. Hãy xuất bản sao lưu.');throw e});storageEngine.queue.catch(()=>{});}
async function flushLearningData(){await storageEngine.queue;if(storageEngine.error)throw Error(storageEngine.error)}
async function putOriginalFiles(records){if(!storageEngine.db)throw Error('Chưa mở được bộ nhớ tệp. Tải lại hoặc xuất hồ sơ trước.');await flushLearningData();const all=await dbRead('files'),bytes=all.reduce((n,f)=>n+f.blob.size,0)+records.reduce((n,f)=>n+f.blob.size,0);if(bytes>MAX_FILES_TOTAL)throw Error('Bản này hỗ trợ tối đa 50 MB tài liệu trên máy.');await dbWrite(['files'],tx=>records.forEach(r=>tx.objectStore('files').put(r)))}
function blobBase64(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('Không đọc được tệp để sao lưu.'));r.readAsDataURL(blob)})}
async function makeBackup(){await storageEngine.queue.catch(()=>{});const rows=storageEngine.db?await dbRead('files').catch(()=>[]):[];const files=[];for(const f of rows)if(state.files.some(x=>x.id===f.id))files.push({id:f.id,name:f.name,type:f.blob.type||'application/octet-stream',bytes:f.blob.size,data:await blobBase64(f.blob)});const data=checkedState(state),included=new Set(files.map(f=>f.id));data.files.forEach(f=>{if(!included.has(f.id))f.hasBlob=false});return {format:BACKUP_FORMAT,version:BACKUP_VERSION,createdAt:new Date().toISOString(),data,files}}
function parseBackup(text){let pack;try{pack=JSON.parse(text)}catch{throw Error('Không đọc được JSON sao lưu.')}if(pack?.format!==BACKUP_FORMAT||pack.version!==BACKUP_VERSION||!Array.isArray(pack.files)||pack.files.length>1000)throw Error('Đây không phải bản sao lưu Nhịp học phiên bản được hỗ trợ.');const data=checkedState(pack.data),seen=new Set(),files=[];let total=0;for(const f of pack.files){if(!f||!validId(f.id)||seen.has(f.id)||!data.files.some(x=>x.id===f.id)||typeof f.data!=='string'||f.data.length>Math.ceil(MAX_FILE*4/3)+4||!/^[A-Za-z0-9+/]*={0,2}$/.test(f.data)||f.data.length%4!==0)throw Error('Tệp đính kèm trong bản sao lưu không hợp lệ.');let raw;try{raw=atob(f.data)}catch{throw Error('Tệp sao lưu bị hỏng.')}if(raw.length>MAX_FILE||raw.length!==f.bytes)throw Error('Kích thước tệp sao lưu không khớp.');total+=raw.length;if(total>MAX_FILES_TOTAL)throw Error('Bản sao lưu vượt giới hạn 50 MB tệp.');seen.add(f.id);files.push({id:f.id,name:cleanString(f.name,300),blob:new Blob([Uint8Array.from(raw,c=>c.charCodeAt(0))],{type:cleanString(f.type,150)||'application/octet-stream'})})}data.files.forEach(f=>f.hasBlob=seen.has(f.id));return {data,files,total,createdAt:cleanString(pack.createdAt,40)}}
async function replaceWorkspace(preview){if(!storageEngine.db)throw Error('Cần mở được IndexedDB để khôi phục an toàn.');await storageEngine.queue.catch(()=>{});const previous={data:structuredClone(state),files:await dbRead('files')};preview.data.updatedAt=new Date().toISOString();await dbWrite(['workspace','files'],tx=>{const ws=tx.objectStore('workspace'),fs=tx.objectStore('files');ws.put(previous,'previous');ws.put(preview.data,'current');fs.clear();preview.files.forEach(f=>fs.put(f))});state=preview.data;storageEngine.hasPrevious=true;storageEngine.lastSaved=state.updatedAt;storageEngine.error='';try{localStorage.setItem('nhiphoc-v2',JSON.stringify(state))}catch{}courseId=state.courses[0].id;}
async function bootLearningApp(){const el=$('#content');el.innerHTML='<div class="empty">Đang mở hồ sơ học trên máy…</div>';try{storageEngine.db=await openLearningDB();const stored=await dbRead('workspace','current');if(stored){const disk=checkedState(stored);let local;try{local=checkedState(state)}catch{}state=local&&Date.parse(local.updatedAt)>Date.parse(disk.updatedAt)?local:disk}else state=checkedState(state);storageEngine.hasPrevious=!!(await dbRead('workspace','previous'));storageEngine.ready=true;save();await flushLearningData()}catch(e){storageEngine.error=e.message||'Không mở được bộ nhớ.';storageEngine.ready=true;state=checkedState(state)}ensureLearningFields();readHash();storageLabel(storageEngine.db&&!storageEngine.error?'✓ Đã lưu trên máy':'Lưu tạm · cần xuất sao lưu');}
